// Runs whenever a LendLoop workflow fails after its retries, so failures are never silent.
// The execution is also kept in n8n's Executions list (saveDataErrorExecution = all).
// Replace console.error with a Slack/email alert in production.
const e = $input.first().json;
const summary = {
  workflow: e.workflow?.name,
  executionId: e.execution?.id,
  url: e.execution?.url,
  failedNode: e.execution?.lastNodeExecuted,
  error: e.execution?.error?.message,
  at: new Date().toISOString(),
};
console.error('[LendLoop ALERT] workflow failed', JSON.stringify(summary));
return [{ json: summary }];
